#include <string>
#include <vector>

class Solution {
public:
    int countPoints(std::string rings) {
        std::vector<int> rods(10, 0);
        for (int i = 0; i < (int)rings.size(); i += 2) {
            char color = rings[i];
            int rod = rings[i + 1] - '0';
            int bit = color == 'R' ? 1 : (color == 'G' ? 2 : 4);
            rods[rod] |= bit;
        }
        int ans = 0;
        for (int mask : rods) {
            if (mask == 7) ans++;
        }
        return ans;
    }
};

class Solution {
    public int countPoints(String rings) {
        int[] rods = new int[10];
        for (int i = 0; i < rings.length(); i += 2) {
            char color = rings.charAt(i);
            int rod = rings.charAt(i + 1) - '0';
            int bit = color == 'R' ? 1 : (color == 'G' ? 2 : 4);
            rods[rod] |= bit;
        }
        int ans = 0;
        for (int mask : rods) {
            if (mask == 7) ans++;
        }
        return ans;
    }
}

/**
 * @param {string} rings
 * @return {number}
 */
var countPoints = function(rings) {
    const rods = new Array(10).fill(0);
    const colorMask = { R: 1, G: 2, B: 4 };

    for (let i = 0; i < rings.length; i += 2) {
        const color = rings[i];
        const rod = Number(rings[i + 1]);
        rods[rod] |= colorMask[color];
    }

    return rods.filter(mask => mask === 7).length;
};
